#!/usr/bin/env python3
"""Generate a deterministic 10-bit phase / Q1.15 sine-cosine ROM."""

import math
import io
from pathlib import Path

p = Path(__file__).resolve().parents[1] / "rtl/nco_rom.v"
with io.StringIO() as f:
    f.write(
        "// Generated by scripts/generate_rom.py\nmodule nco_rom(input [9:0] addr, output reg [31:0] data);\nalways @* case(addr)\n"
    )
    for n in range(1024):
        c = round(32767 * math.cos(2 * math.pi * n / 1024)) & 65535
        s = round(32767 * math.sin(2 * math.pi * n / 1024)) & 65535
        f.write(f"10'd{n}: data=32'h{s:04x}{c:04x};\n")
    f.write("default: data=0;\nendcase\nendmodule\n")
    text = f.getvalue()
    if not p.exists() or p.read_text() != text:
        p.write_text(text)
